1	<!DOCTYPE html>
2	<html lang="en" data-theme="dark">
3	
4	<head>
5	  <meta charset="UTF-8">
6	  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
7	  <title>Project Entry — Table Template Architect</title>
8	  <link rel="preconnect" href="https://fonts.googleapis.com">
9	  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
10	  <link rel="stylesheet"
11	    href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap">
12	  <style>
13	    /* ==========================================================================
14	       PROJECT ENTRY — SCHEMA & TABLE TEMPLATE ARCHITECT
15	       Crafted to the aesthetic standard of Entropy / Rose
16	       ========================================================================== */
17	    :root {
18	      --bg-canvas: #080706;
19	      --bg-card: #13100d;
20	      --bg-card-hover: #1c1713;
21	      --bg-input: #1a1511;
22	      --bg-input-focus: #231c16;
23	
24	      --text-vivid: #fffcf7;
25	      --text-main: #ede4d8;
26	      --text-muted: #8a7b6c;
27	      --text-dim: #5c5044;
28	
29	      --border-dim: #292018;
30	      --border-mid: #3f3226;
31	      --border-bright: #634f3c;
32	
33	      --accent: #ff9e1b;
34	      --accent-hover: #ffb03a;
35	      --accent-glow: rgba(255, 158, 27, 0.25);
36	      --accent-bg: rgba(255, 158, 27, 0.12);
37	      --accent-border: rgba(255, 158, 27, 0.4);
38	
39	      --hazard-high: #f43f5e;
40	      --hazard-low: #10b981;
41	      --hazard-mid: #f59e0b;
42	
43	      --radius-sm: 6px;
44	      --radius-md: 10px;
45	      --radius-lg: 14px;
46	      --shadow-subtle: 0 4px 20px rgba(0, 0, 0, 0.5);
47	
48	      color-scheme: dark;
49	      font-family: "IBM Plex Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
50	      font-size: 14.5px;
51	      line-height: 1.5;
52	    }
53	
54	    :root[data-theme="light"] {
55	      --bg-canvas: #f5f3ef;
56	      --bg-card: #ffffff;
57	      --bg-card-hover: #f9f7f4;
58	      --bg-input: #f0ebe3;
59	      --bg-input-focus: #ffffff;
60	
61	      --text-vivid: #18130e;
62	      --text-main: #2c231a;
63	      --text-muted: #6b5a49;
64	      --text-dim: #9e8c79;
65	
66	      --border-dim: #ded5c7;
67	      --border-mid: #c5b8a5;
68	      --border-bright: #8f7d67;
69	
70	      --accent: #d97706;
71	      --accent-hover: #b45309;
72	      --accent-glow: rgba(217, 119, 6, 0.2);
73	      --accent-bg: rgba(217, 119, 6, 0.1);
74	      --accent-border: rgba(217, 119, 6, 0.4);
75	
76	      --hazard-high: #e11d48;
77	      --hazard-low: #059669;
78	      --hazard-mid: #d97706;
79	
80	      color-scheme: light;
81	    }
82	
83	    * {
84	      box-sizing: border-box;
85	      margin: 0;
86	      padding: 0;
87	    }
88	
89	    html,
90	    body {
91	      min-height: 100%;
92	    }
93	
94	    body {
95	      background: var(--bg-canvas);
96	      color: var(--text-main);
97	      padding: 1.5rem 1.5rem 4rem;
98	      display: flex;
99	      justify-content: center;
100	      overflow-x: hidden;
101	    }
102	
103	    .app-container {
104	      width: 100%;
105	      max-width: 1440px;
106	      display: flex;
107	      flex-direction: column;
108	      gap: 1.5rem;
109	    }
110	
111	    /* Top Navigation */
112	    .top-bar {
113	      display: flex;
114	      justify-content: space-between;
115	      align-items: center;
116	      border-bottom: 1px solid var(--border-dim);
117	      padding-bottom: 1rem;
118	      flex-wrap: wrap;
119	      gap: 1rem;
120	    }
121	
122	    .title-stack h1 {
123	      font-size: 1.4rem;
124	      font-weight: 700;
125	      color: var(--text-vivid);
126	      display: flex;
127	      align-items: center;
128	      gap: 0.5rem;
129	    }
130	
131	    .title-stack h1 .badge {
132	      font-family: "JetBrains Mono", monospace;
133	      font-size: 0.72rem;
134	      font-weight: 700;
135	      color: var(--accent);
136	      background: var(--accent-bg);
137	      border: 1px solid var(--accent-border);
138	      padding: 0.2rem 0.5rem;
139	      border-radius: 4px;
140	      text-transform: uppercase;
141	    }
142	
143	    .title-sub {
144	      font-size: 0.8rem;
145	      color: var(--text-muted);
146	      margin-top: 0.2rem;
147	    }
148	
149	    /* Table Navigation Tabs */
150	    .nav-tabs-bar {
151	      display: flex;
152	      gap: 0.4rem;
153	      flex-wrap: wrap;
154	      background: var(--bg-card);
155	      border: 1px solid var(--border-dim);
156	      padding: 0.35rem;
157	      border-radius: var(--radius-md);
158	    }
159	
160	    .nav-tab-btn {
161	      background: transparent;
162	      border: 1px solid transparent;
163	      color: var(--text-muted);
164	      padding: 0.5rem 0.9rem;
165	      border-radius: var(--radius-sm);
166	      font-size: 0.88rem;
167	      font-weight: 600;
168	      cursor: pointer;
169	      display: inline-flex;
170	      align-items: center;
171	      gap: 0.45rem;
172	      transition: all 0.15s ease;
173	      font-family: "JetBrains Mono", monospace;
174	    }
175	
176	    .nav-tab-btn:hover {
177	      color: var(--text-vivid);
178	      background: var(--bg-input);
179	    }
180	
181	    .nav-tab-btn.active {
182	      background: var(--accent-bg);
183	      border-color: var(--accent-border);
184	      color: var(--accent);
185	      font-weight: 700;
186	    }
187	
188	    .btn-action {
189	      background: var(--bg-card);
190	      border: 1px solid var(--border-mid);
191	      color: var(--text-main);
192	      padding: 0.5rem 0.85rem;
193	      border-radius: var(--radius-sm);
194	      font-size: 0.82rem;
195	      font-weight: 600;
196	      cursor: pointer;
197	      display: inline-flex;
198	      align-items: center;
199	      gap: 0.4rem;
200	      transition: all 0.15s ease;
201	      font-family: inherit;
202	    }
203	
204	    .btn-action:hover {
205	      background: var(--bg-card-hover);
206	      border-color: var(--accent);
207	      color: var(--text-vivid);
208	    }
209	
210	    .btn-action.btn-primary {
211	      background: var(--accent);
212	      border-color: var(--accent);
213	      color: #080706;
214	      font-weight: 700;
215	    }
216	
217	    .btn-action.btn-primary:hover {
218	      background: var(--accent-hover);
219	      border-color: var(--accent-hover);
220	    }
221	
222	    .btn-action.btn-danger:hover {
223	      background: rgba(244, 63, 94, 0.15);
224	      border-color: var(--hazard-high);
225	      color: var(--hazard-high);
226	    }
227	
228	    /* Workspace 2-Column Grid */
229	    .workspace-grid {
230	      display: grid;
231	      grid-template-columns: 1fr 380px;
232	      gap: 1.25rem;
233	      align-items: start;
234	    }
235	
236	    @media (max-width: 860px) {
237	      .workspace-grid {
238	        grid-template-columns: 1fr;
239	      }
240	    }
241	
242	    .blocks-stream {
243	      display: flex;
244	      flex-direction: column;
245	      gap: 1.25rem;
246	    }
247	
248	    /* Cards */
249	    .entry-card {
250	      background: var(--bg-card);
251	      border: 1px solid var(--border-dim);
252	      border-radius: var(--radius-md);
253	      overflow: visible !important;
254	      position: relative;
255	      box-shadow: var(--shadow-subtle);
256	      transition: border-color 0.15s ease;
257	    }
258	
259	    .entry-card:focus-within {
260	      border-color: var(--border-mid);
261	    }
262	
263	    .card-header {
264	      padding: 0.85rem 1.15rem;
265	      background: rgba(255, 255, 255, 0.015);
266	      border-bottom: 1px solid var(--border-dim);
267	      display: flex;
268	      justify-content: space-between;
269	      align-items: center;
270	      user-select: none;
271	    }
272	
273	    .card-title {
274	      font-size: 0.92rem;
275	      font-weight: 700;
276	      color: var(--text-vivid);
277	      display: flex;
278	      align-items: center;
279	      gap: 0.5rem;
280	    }
281	
282	    /* Category Theming & Visual Distinction */
283	    .entry-card.cat-pk {
284	      border-left: 4px solid #38bdf8;
285	    }
286	
287	    .entry-card.cat-pk .card-header {
288	      background: rgba(56, 189, 248, 0.05);
289	    }
290	
291	    .entry-card.cat-text {
292	      border-left: 4px solid #10b981;
293	    }
294	
295	    .entry-card.cat-text .card-header {
296	      background: rgba(16, 185, 129, 0.05);
297	    }
298	
299	    .entry-card.cat-scalar {
300	      border-left: 4px solid #f59e0b;
301	    }
302	
303	    .entry-card.cat-scalar .card-header {
304	      background: rgba(245, 158, 11, 0.05);
305	    }
306	
307	    .entry-card.cat-boolean {
308	      border-left: 4px solid #a855f7;
309	    }
310	
311	    .entry-card.cat-boolean .card-header {
312	      background: rgba(168, 85, 247, 0.05);
313	    }
314	
315	    .entry-card.cat-enum {
316	      border-left: 4px solid #f43f5e;
317	    }
318	
319	    .entry-card.cat-enum .card-header {
320	      background: rgba(244, 63, 94, 0.05);
321	    }
322	
323	    .entry-card.cat-rel {
324	      border-left: 4px solid #ff9e1b;
325	    }
326	
327	    .entry-card.cat-rel .card-header {
328	      background: rgba(255, 158, 27, 0.05);
329	    }
330	
331	    /* Collapsed Card State */
332	    .entry-card.collapsed .card-body {
333	      display: none;
334	    }
335	
336	    .entry-card.collapsed {
337	      box-shadow: none;
338	    }
339	
340	    .entry-card.collapsed .card-header {
341	      border-bottom: none;
342	      padding: 0.65rem 1rem;
343	    }
344	
345	    .collapse-chevron {
346	      color: var(--text-dim);
347	      font-size: 0.75rem;
348	      cursor: pointer;
349	      user-select: none;
350	      transition: transform 0.2s ease, color 0.15s ease;
351	      display: inline-flex;
352	      align-items: center;
353	      justify-content: center;
354	      width: 18px;
355	      height: 18px;
356	    }
357	
358	    .collapse-chevron:hover {
359	      color: var(--accent);
360	    }
361	
362	    .entry-card.collapsed .collapse-chevron {
363	      transform: rotate(-90deg);
364	    }
365	
366	    .card-tag {
367	      font-family: "JetBrains Mono", monospace;
368	      font-size: 0.7rem;
369	      font-weight: 700;
370	      color: var(--accent);
371	      background: var(--accent-bg);
372	      padding: 0.15rem 0.45rem;
373	      border-radius: 4px;
374	      border: 1px solid var(--accent-border);
375	      text-transform: uppercase;
376	      letter-spacing: 0.04em;
377	    }
378	
379	    .card-tag.cat-pk {
380	      color: #38bdf8;
381	      background: rgba(56, 189, 248, 0.12);
382	      border-color: rgba(56, 189, 248, 0.4);
383	    }
384	
385	    .card-tag.cat-text {
386	      color: #10b981;
387	      background: rgba(16, 185, 129, 0.12);
388	      border-color: rgba(16, 185, 129, 0.4);
389	    }
390	
391	    .card-tag.cat-scalar {
392	      color: #f59e0b;
393	      background: rgba(245, 158, 11, 0.12);
394	      border-color: rgba(245, 158, 11, 0.4);
395	    }
396	
397	    .card-tag.cat-boolean {
398	      color: #c084fc;
399	      background: rgba(168, 85, 247, 0.12);
400	      border-color: rgba(168, 85, 247, 0.4);
401	    }
402	
403	    .card-tag.cat-enum {
404	      color: #fb7185;
405	      background: rgba(244, 63, 94, 0.12);
406	      border-color: rgba(244, 63, 94, 0.4);
407	    }
408	
409	    .card-tag.cat-rel {
410	      color: #ff9e1b;
411	      background: rgba(255, 158, 27, 0.12);
412	      border-color: rgba(255, 158, 27, 0.4);
413	    }
414	
415	    .slug-badge {
416	      font-family: "JetBrains Mono", monospace;
417	      font-size: 0.76rem;
418	      color: var(--text-dim);
419	      background: var(--bg-input);
420	      border: 1px solid var(--border-dim);
421	      padding: 0.15rem 0.45rem;
422	      border-radius: 4px;
423	    }
424	
425	    /* Filter Toolbar above stream */
426	    .stream-toolbar {
427	      display: flex;
428	      justify-content: space-between;
429	      align-items: center;
430	      flex-wrap: wrap;
431	      gap: 0.75rem;
432	      padding: 0.5rem 0;
433	    }
434	
435	    .filter-pills-bar {
436	      display: flex;
437	      gap: 0.35rem;
438	      flex-wrap: wrap;
439	    }
440	
441	    .filter-pill {
442	      background: var(--bg-card);
443	      border: 1px solid var(--border-dim);
444	      color: var(--text-muted);
445	      padding: 0.3rem 0.65rem;
446	      border-radius: var(--radius-sm);
447	      font-size: 0.76rem;
448	      font-weight: 600;
449	      cursor: pointer;
450	      display: inline-flex;
451	      align-items: center;
452	      gap: 0.35rem;
453	      transition: all 0.15s ease;
454	      font-family: inherit;
455	    }
456	
457	    .filter-pill:hover {
458	      background: var(--bg-card-hover);
459	      color: var(--text-vivid);
460	    }
461	
462	    .filter-pill.active {
463	      background: var(--accent-bg);
464	      border-color: var(--accent-border);
465	      color: var(--accent);
466	      font-weight: 700;
467	    }
468	
469	    .card-body {
470	      padding: 1.15rem;
471	      display: flex;
472	      flex-direction: column;
473	      gap: 1.1rem;
474	    }
475	
476	    .field-label {
477	      display: flex;
478	      justify-content: space-between;
479	      align-items: center;
480	      font-size: 0.8rem;
481	      font-weight: 600;
482	      color: var(--text-muted);
483	      margin-bottom: 0.35rem;
484	    }
485	
486	    .field-hint {
487	      font-size: 0.72rem;
488	      color: var(--text-dim);
489	      font-family: "JetBrains Mono", monospace;
490	    }
491	
492	    /* Inputs */
493	    .raw-input-box {
494	      width: 100%;
495	      height: 42px;
496	      background: var(--bg-input);
497	      border: 1px solid var(--border-dim);
498	      border-radius: var(--radius-sm);
499	      color: var(--text-vivid);
500	      font-family: inherit;
501	      font-size: 0.9rem;
502	      padding: 0 0.85rem;
503	      outline: none;
504	      transition: all 0.15s ease;
505	    }
506	
507	    .raw-input-box.mono {
508	      font-family: "JetBrains Mono", monospace;
509	      font-size: 0.85rem;
510	    }
511	
512	    .raw-input-box:focus {
513	      background: var(--bg-input-focus);
514	      border-color: var(--accent);
515	      box-shadow: 0 0 0 3px var(--accent-glow);
516	    }
517	
518	    select.raw-input-box {
519	      cursor: pointer;
520	      appearance: none;
521	      background-image: url("data:image/svg+xml,%3Csvg width='8' height='6' viewBox='0 0 8 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L4 4.5L7 1.5' stroke='%23ff9e1b' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
522	      background-repeat: no-repeat;
523	      background-position: right 12px center;
524	      padding-right: 2rem;
525	    }
526	
527	    /* Two-col field row */
528	    .field-grid-2 {
529	      display: grid;
530	      grid-template-columns: 1fr 1fr;
531	      gap: 1rem;
532	    }
533	
534	    @media (max-width: 640px) {
535	      .field-grid-2 {
536	        grid-template-columns: 1fr;
537	      }
538	    }
539	
540	    /* Governance Badge Box */
541	    .governance-box {
542	      padding: 0.75rem 0.9rem;
543	      border-radius: var(--radius-sm);
544	      font-size: 0.8rem;
545	      display: flex;
546	      flex-direction: column;
547	      gap: 0.3rem;
548	      background: var(--bg-input);
549	      border: 1px solid var(--border-mid);
550	    }
551	
552	    .governance-box.warning {
553	      background: rgba(245, 158, 11, 0.08);
554	      border-color: rgba(245, 158, 11, 0.4);
555	      color: var(--hazard-mid);
556	    }
557	
558	    .governance-box.danger {
559	      background: rgba(244, 63, 94, 0.08);
560	      border-color: rgba(244, 63, 94, 0.4);
561	      color: var(--hazard-high);
562	    }
563	
564	    .governance-box.info {
565	      background: rgba(56, 189, 248, 0.08);
566	      border-color: rgba(56, 189, 248, 0.4);
567	      color: #38bdf8;
568	    }
569	
570	    .governance-box.success {
571	      background: rgba(16, 185, 129, 0.08);
572	      border-color: rgba(16, 185, 129, 0.4);
573	      color: var(--hazard-low);
574	    }
575	
576	    .governance-title {
577	      font-weight: 700;
578	      font-size: 0.76rem;
579	      text-transform: uppercase;
580	      letter-spacing: 0.05em;
581	      display: flex;
582	      align-items: center;
583	      gap: 0.35rem;
584	    }
585	
586	    /* Chips & Tags */
587	    .chips-pool {
588	      display: flex;
589	      flex-wrap: wrap;
590	      gap: 0.4rem;
591	      align-items: center;
592	    }
593	
594	    .chip-badge {
595	      display: inline-flex;
596	      align-items: center;
597	      gap: 0.35rem;
598	      background: var(--accent-bg);
599	      color: var(--accent);
600	      border: 1px solid var(--accent-border);
601	      padding: 0.25rem 0.6rem;
602	      border-radius: 4px;
603	      font-size: 0.82rem;
604	      font-weight: 600;
605	      font-family: "JetBrains Mono", monospace;
606	      user-select: none;
607	    }
608	
609	    .chip-remove {
610	      cursor: pointer;
611	      opacity: 0.7;
612	      font-size: 0.8rem;
613	      padding: 0 2px;
614	      border-radius: 2px;
615	      transition: all 0.1s ease;
616	    }
617	
618	    .chip-remove:hover {
619	      opacity: 1;
620	      background: rgba(244, 63, 94, 0.2);
621	      color: #fb7185;
622	    }
623	
624	    .chip-add-input {
625	      height: 32px;
626	      background: var(--bg-input);
627	      border: 1px dashed var(--border-mid);
628	      border-radius: 4px;
629	      color: var(--text-vivid);
630	      padding: 0 0.6rem;
631	      font-size: 0.82rem;
632	      font-family: "JetBrains Mono", monospace;
633	      outline: none;
634	      width: 140px;
635	    }
636	
637	    .chip-add-input:focus {
638	      border-color: var(--accent);
639	      border-style: solid;
640	      background: var(--bg-input-focus);
641	    }
642	
643	    /* Quick Add Bar */
644	    .quick-add-section {
645	      background: var(--bg-card);
646	      border: 1px dashed var(--border-mid);
647	      border-radius: var(--radius-md);
648	      padding: 1.25rem;
649	      display: flex;
650	      flex-direction: column;
651	      gap: 0.85rem;
652	    }
653	
654	    .quick-add-title {
655	      font-size: 0.85rem;
656	      font-weight: 700;
657	      color: var(--text-muted);
658	      text-transform: uppercase;
659	      letter-spacing: 0.05em;
660	      display: flex;
661	      justify-content: space-between;
662	      align-items: center;
663	    }
664	
665	    .quick-add-grid {
666	      display: grid;
667	      grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
668	      gap: 0.5rem;
669	    }
670	
671	    .quick-add-btn {
672	      background: var(--bg-input);
673	      border: 1px solid var(--border-dim);
674	      border-radius: var(--radius-sm);
675	      padding: 0.55rem 0.75rem;
676	      color: var(--text-main);
677	      cursor: pointer;
678	      display: flex;
679	      flex-direction: column;
680	      align-items: flex-start;
681	      gap: 0.2rem;
682	      transition: all 0.15s ease;
683	      font-family: inherit;
684	      text-align: left;
685	    }
686	
687	    .quick-add-btn:hover {
688	      background: var(--bg-card-hover);
689	      border-color: var(--accent);
690	      transform: translateY(-1px);
