1749	    function generateSqlDDL(table) {
1750	      if (!table || !table.columns) return '-- No table active';
1751	      const lines = [`CREATE TABLE IF NOT EXISTS ${table.table_name} (`];
1752	      const cols = table.columns.map(col => {
1753	        let sqlType = 'TEXT';
1754	        switch (col.type) {
1755	          case 'hex_id': sqlType = 'TEXT PRIMARY KEY'; break;
1756	          case 'int_scalar': sqlType = 'INTEGER'; break;
1757	          case 'float_scalar': sqlType = 'REAL'; break;
1758	          case 'boolean': sqlType = 'INTEGER DEFAULT 0'; break;
1759	          case 'enum_multi': sqlType = 'TEXT -- JSON Array'; break;
1760	          case 'relation_multi': sqlType = 'TEXT -- JSON Array of Hex IDs'; break;
1761	          case 'relation_single': sqlType = 'TEXT -- Foreign Hex ID'; break;
1762	          default: sqlType = 'TEXT';
1763	        }
1764	        const colIdentifier = col.slug || toSlug(col.name) || 'unnamed_field';
1765	        return `    ${colIdentifier.padEnd(20, ' ')} ${sqlType}`;
1766	      });
1767	      lines.push(cols.join(',\n'));
1768	      lines.push(');');
1769	      return lines.join('\n');
1770	    }
