1778	        titleView.textContent = `SQLite DDL (${activeTable}.sql)`;
1779	        codeView.textContent = generateSqlDDL(table);
1780	      } else if (activeInspectorTab === 'json') {
1781	        titleView.textContent = `JSON Config (${activeTable}.json)`;
1782	        codeView.textContent = JSON.stringify(table, null, 2);
1783	      } else if (activeInspectorTab === 'info') {
1784	        titleView.textContent = 'SQLite Database Info';
1785	        if (isServerConnected) {
1786	          try {
