865	
866	  <script>
867	    /* ========================================================================
868	       STANDALONE TABLE SCHEMA EDITOR — EMBEDDED MOCK DATA
869	       ======================================================================== */
870	
871	    const FIELD_TYPES = {
872	      hex_id: { category: 'pk', icon: '🔑', title: 'Hex ID', sql: 'TEXT PRIMARY KEY' },
873	      text_single: { category: 'text', icon: '📝', title: 'Text (single)', sql: 'TEXT' },
874	      text_multi: { category: 'text', icon: '📝', title: 'Text (multi)', sql: 'TEXT' },
875	      int_scalar: { category: 'scalar', icon: '🔢', title: 'Integer', sql: 'INTEGER' },
876	      float_scalar: { category: 'scalar', icon: '🔢', title: 'Float', sql: 'REAL' },
877	      boolean: { category: 'boolean', icon: '🔘', title: 'Boolean', sql: 'INTEGER DEFAULT 0' },
878	      enum_single: { category: 'enum', icon: '🏷️', title: 'Enum (single)', sql: 'TEXT' },
879	      enum_multi: { category: 'enum', icon: '🏷️', title: 'Enum (multi)', sql: 'TEXT (JSON)' },
880	      relation_single: { category: 'rel', icon: '🔗', title: 'Relation (single)', sql: 'TEXT' },
881	      relation_multi: { category: 'rel', icon: '🔗', title: 'Relation (multi)', sql: 'TEXT (JSON)' }
882	    };
883	
884	    const MOCK_DATA = {
885	      users: {
886	        table_name: 'users',
887	        columns: [
888	          { name: 'User ID', slug: 'id', type: 'hex_id', metadata: { prefix: 'USER' } },
889	          { name: 'Username', slug: 'username', type: 'text_single', metadata: {} },
890	          { name: 'Email', slug: 'email', type: 'text_single', metadata: {} },
891	          { name: 'Bio', slug: 'bio', type: 'text_multi', metadata: {} },
892	          { name: 'Age', slug: 'age', type: 'int_scalar', metadata: {} },
893	          { name: 'Balance', slug: 'balance', type: 'float_scalar', metadata: {} },
894	          { name: 'Active', slug: 'is_active', type: 'boolean', metadata: {} },
895	          { name: 'Role', slug: 'role', type: 'enum_single', metadata: { options: ['admin', 'editor', 'viewer'] } },
896	          { name: 'Tags', slug: 'tags', type: 'enum_multi', metadata: { options: ['premium', 'verified', 'staff'] } },
897	          { name: 'Manager', slug: 'manager_id', type: 'relation_single', metadata: { target: 'users' } },
898	          { name: 'Projects', slug: 'project_ids', type: 'relation_multi', metadata: { target: 'projects' } }
899	        ]
900	      },
901	      projects: {
902	        table_name: 'projects',
903	        columns: [
904	          { name: 'Project ID', slug: 'id', type: 'hex_id', metadata: { prefix: 'PROJ' } },
905	          { name: 'Title', slug: 'title', type: 'text_single', metadata: {} },
906	          { name: 'Description', slug: 'description', type: 'text_multi', metadata: {} },
907	          { name: 'Budget', slug: 'budget', type: 'float_scalar', metadata: {} },
908	          { name: 'Status', slug: 'status', type: 'enum_single', metadata: { options: ['planning', 'active', 'completed'] } },
909	          { name: 'Public', slug: 'is_public', type: 'boolean', metadata: {} },
910	          { name: 'Owner', slug: 'owner_id', type: 'relation_single', metadata: { target: 'users' } },
911	          { name: 'Team Members', slug: 'member_ids', type: 'relation_multi', metadata: { target: 'users' } }
912	        ]
913	      }
914	    };
915	
916	    let tables = JSON.parse(JSON.stringify(MOCK_DATA));
917	    let activeTable = 'users';
918	    let activeTab = 'sql';
919	    let activeFilter = 'all';
920	
921	    function init() {
922	      renderTableTabs();
923	      renderColumns();
924	      renderFilters();
925	      updateInspector();
926	    }
927	
928	    function renderTableTabs() {
929	      const container = document.getElementById('table-tabs');
930	      const names = Object.keys(tables);
931	      container.innerHTML = names.map(name => `
932	        <button class="tab-btn ${name === activeTable ? 'active' : ''}" onclick="switchTable('${name}')">
933	          📁 ${name}
934	        </button>
935	      `).join('') + `
936	        <button class="tab-btn" onclick="createTable()" style="border-style: dashed; border-color: var(--border-mid);">
937	          + New Table
938	        </button>
939	      `;
940	    }
941	
942	    function switchTable(name) {
943	      if (!tables[name]) return;
944	      activeTable = name;
945	      document.getElementById('active-table-name').textContent = name;
946	      document.getElementById('table-name-input').value = name;
947	      renderTableTabs();
948	      renderColumns();
949	      updateInspector();
950	    }
951	
952	    function createTable() {
953	      const name = prompt('Table name (e.g., tasks, inventory):');
954	      if (!name) return;
955	      const clean = name.toLowerCase().replace(/[^a-z0-9_]/g, '_');
956	      if (tables[clean]) {
957	        alert('Table already exists');
958	        return;
959	      }
960	      tables[clean] = {
961	        table_name: clean,
962	        columns: [{ name: 'ID', slug: 'id', type: 'hex_id', metadata: { prefix: clean.substring(0, 4).toUpperCase() } }]
963	      };
964	      switchTable(clean);
965	      showToast(`Created table "${clean}"`);
966	    }
967	
968	    function renderFilters() {
969	      const bar = document.getElementById('filter-bar');
970	      const categories = ['all', 'pk', 'text', 'scalar', 'boolean', 'enum', 'rel'];
971	      const icons = { all: '📊', pk: '🔑', text: '📝', scalar: '🔢', boolean: '🔘', enum: '🏷️', rel: '🔗' };
972	      bar.innerHTML = categories.map(cat => `
973	        <button class="filter-btn ${cat === activeFilter ? 'active' : ''}" onclick="setFilter('${cat}')">
974	          ${icons[cat]} ${cat === 'all' ? 'All' : cat.charAt(0).toUpperCase() + cat.slice(1)}
975	        </button>
976	      `).join('');
977	    }
978	
979	    function setFilter(cat) {
980	      activeFilter = cat;
981	      renderFilters();
982	      renderColumns();
983	    }
984	
985	    function renderColumns() {
986	      if (!tables[activeTable]) return;
987	      const table = tables[activeTable];
988	      const stream = document.getElementById('columns-stream');
989	
990	      const columnCount = table.columns.length;
991	      document.getElementById('columns-count').textContent = `${columnCount} column${columnCount !== 1 ? 's' : ''}`;
992	
993	      const filtered = activeFilter === 'all'
994	        ? table.columns
995	        : table.columns.filter(col => FIELD_TYPES[col.type]?.category === activeFilter);
996	
997	      if (filtered.length === 0) {
998	        stream.innerHTML = '<div style="padding: 3rem 1.5rem; text-align: center; color: var(--text-dim);">No columns in this category</div>';
999	        return;
1000	      }
1001	
1002	      stream.innerHTML = filtered.map((col, idx) => renderColumnCard(col, idx)).join('');
1003	    }
1004	
1005	    function renderColumnCard(col, idx) {
1006	      const type = FIELD_TYPES[col.type];
1007	      return `
1008	        <section class="card column-card ${type.category}">
1009	          <div class="column-card-header">
1010	            <div class="column-card-title">
1011	              <span class="column-icon">${type.icon}</span>
1012	              <span class="column-number">#${idx + 1}</span>
1013	              <span class="column-name">${col.name}</span>
1014	            </div>
1015	            <div style="display: flex; gap: 0.5rem; align-items: center;">
1016	              <span class="column-tag">${type.title}</span>
1017	              <button class="btn small icon-only" onclick="deleteColumn(${idx})" title="Delete">✕</button>
1018	            </div>
1019	          </div>
1020	          <div class="column-card-body">
1021	            <div class="field-grid-2">
1022	              <div class="field-group">
1023	                <label class="field-label">Column Name</label>
1024	                <input type="text" value="${col.name}" onchange="updateColumnName(${idx}, this.value)">
1025	              </div>
1026	              <div class="field-group">
1027	                <label class="field-label">Column Type</label>
1028	                <select onchange="updateColumnType(${idx}, this.value)">
1029	                  ${Object.entries(FIELD_TYPES).map(([slug, info]) => `
1030	                    <option value="${slug}" ${col.type === slug ? 'selected' : ''}>
1031	                      ${info.icon} ${info.title}
1032	                    </option>
1033	                  `).join('')}
1034	                </select>
1035	              </div>
1036	            </div>
1037	            ${renderMetadata(col, idx)}
1038	          </div>
1039	        </section>
1040	      `;
1041	    }
1042	
1043	    function renderMetadata(col, idx) {
1044	      const meta = col.metadata || {};
1045	      if (col.type === 'hex_id') {
1046	        return `
1047	          <div class="field-group">
1048	            <label class="field-label">ID Prefix (4 chars)</label>
1049	            <input type="text" maxlength="4" value="${meta.prefix || ''}"
1050	              onchange="updateMeta(${idx}, 'prefix', this.value)">
1051	          </div>
1052	        `;
1053	      }
1054	      if (col.type.startsWith('enum_')) {
1055	        const options = Array.isArray(meta.options) ? meta.options : [];
1056	        return `
1057	          <div class="field-group">
1058	            <label class="field-label">Options</label>
1059	            <div style="display: flex; flex-wrap: wrap; gap: 0.5rem;">
1060	              ${options.map((opt, i) => `
1061	                <span style="background: var(--accent-bg); color: var(--accent); padding: 0.4rem 0.8rem; border-radius: 4px; font-size: 13px; display: flex; gap: 0.5rem; align-items: center;">
1062	                  ${opt}
1063	                  <button onclick="removeOption(${idx}, ${i})" style="background: none; border: none; cursor: pointer; color: var(--accent); padding: 0;">✕</button>
1064	                </span>
1065	              `).join('')}
1066	            </div>
1067	            <input type="text" placeholder="Add option, press Enter"
1068	              onkeydown="if(event.key==='Enter'){addOption(${idx}, this.value); this.value='';}">
1069	          </div>
1070	        `;
1071	      }
1072	      if (col.type.startsWith('relation_')) {
1073	        const target = meta.target || 'self';
1074	        return `
1075	          <div class="field-group">
1076	            <label class="field-label">Target Table</label>
1077	            <select onchange="updateMeta(${idx}, 'target', this.value)">
1078	              <option value="self" ${target === 'self' ? 'selected' : ''}>Self (tree)</option>
1079	              ${Object.keys(tables).map(t => `
1080	                <option value="${t}" ${target === t ? 'selected' : ''}>${t}</option>
1081	              `).join('')}
1082	            </select>
1083	          </div>
1084	        `;
1085	      }
1086	      return '';
1087	    }
1088	
1089	    function addField(type) {
1090	      const table = tables[activeTable];
1091	      const newCol = {
1092	        name: FIELD_TYPES[type].title,
1093	        slug: 'new_field',
1094	        type: type,
1095	        metadata: {}
1096	      };
1097	      if (type.startsWith('enum_')) newCol.metadata.options = ['option1', 'option2'];
1098	      if (type.startsWith('relation_')) newCol.metadata.target = 'self';
1099	      if (type === 'hex_id') newCol.metadata.prefix = activeTable.substring(0, 4).toUpperCase();
1100	      table.columns.push(newCol);
1101	      renderColumns();
1102	      updateInspector();
1103	      showToast(`Added ${FIELD_TYPES[type].title}`);
1104	    }
1105	
1106	    function deleteColumn(idx) {
1107	      const name = tables[activeTable].columns[idx].name;
1108	      tables[activeTable].columns.splice(idx, 1);
1109	      renderColumns();
1110	      updateInspector();
1111	      showToast(`Deleted "${name}"`);
1112	    }
1113	
1114	    function updateColumnName(idx, value) {
1115	      tables[activeTable].columns[idx].name = value;
1116	      updateInspector();
1117	    }
1118	
1119	    function updateColumnType(idx, value) {
1120	      tables[activeTable].columns[idx].type = value;
1121	      tables[activeTable].columns[idx].metadata = {};
1122	      if (value.startsWith('enum_')) tables[activeTable].columns[idx].metadata.options = ['option1'];
1123	      if (value.startsWith('relation_')) tables[activeTable].columns[idx].metadata.target = 'self';
1124	      if (value === 'hex_id') tables[activeTable].columns[idx].metadata.prefix = activeTable.substring(0, 4).toUpperCase();
1125	      renderColumns();
1126	      updateInspector();
1127	    }
1128	
1129	    function updateMeta(idx, key, value) {
1130	      if (!tables[activeTable].columns[idx].metadata) tables[activeTable].columns[idx].metadata = {};
1131	      tables[activeTable].columns[idx].metadata[key] = value;
1132	      updateInspector();
1133	    }
1134	
1135	    function addOption(idx, value) {
1136	      if (!value.trim()) return;
1137	      const meta = tables[activeTable].columns[idx].metadata;
1138	      if (!Array.isArray(meta.options)) meta.options = [];
1139	      if (!meta.options.includes(value)) meta.options.push(value);
1140	      renderColumns();
1141	      updateInspector();
1142	    }
1143	
1144	    function removeOption(idx, optIdx) {
1145	      tables[activeTable].columns[idx].metadata.options.splice(optIdx, 1);
1146	      renderColumns();
1147	      updateInspector();
1148	    }
1149	
1150	    function switchTab(tab) {
1151	      activeTab = tab;
1152	      document.querySelectorAll('.inspector-tab-btn').forEach(b => b.classList.remove('active'));
1153	      event.target.classList.add('active');
1154	      updateInspector();
1155	    }
1156	
1157	    function generateSQL(table) {
1158	      if (!table) return '-- No table';
1159	      const lines = [`CREATE TABLE IF NOT EXISTS ${table.table_name} (`];
1160	      const cols = table.columns.map(col => {
1161	        const type = FIELD_TYPES[col.type];
1162	        return `    ${(col.slug || col.name).padEnd(20)} ${type.sql}`;
1163	      });
1164	      lines.push(cols.join(',\n'));
1165	      lines.push(');');
1166	      return lines.join('\n');
1167	    }
1168	
1169	    function updateInspector() {
1170	      const table = tables[activeTable];
1171	      const codeEl = document.getElementById('code-content');
1172	      const titleEl = document.getElementById('code-title');
1173	
1174	      if (activeTab === 'sql') {
1175	        titleEl.textContent = `CREATE TABLE (${activeTable}.sql)`;
1176	        codeEl.textContent = generateSQL(table);
1177	      } else if (activeTab === 'json') {
1178	        titleEl.textContent = `JSON Schema (${activeTable}.json)`;
1179	        codeEl.textContent = JSON.stringify(table, null, 2);
1180	      } else {
1181	        titleEl.textContent = 'Database Status';
1182	        codeEl.textContent = JSON.stringify({
1183	          mode: 'Standalone (embedded mock data)',
1184	          tables: Object.keys(tables),
1185	          active_table: activeTable,
1186	          column_count: table.columns.length
1187	        }, null, 2);
1188	      }
1189	    }
1190	
1191	    function copyCode() {
1192	      const text = document.getElementById('code-content').textContent;
1193	      navigator.clipboard.writeText(text).then(() => {
1194	        showToast('Copied to clipboard!');
1195	      });
1196	    }
1197	
1198	    function saveTable() {
1199	      localStorage.setItem('project_entry_schemas', JSON.stringify(tables));
1200	      showToast('Saved to local storage');
1201	    }
1202	
1203	    function syncSqlite() {
1204	      showToast('SQLite sync (frontend only in standalone mode)');
1205	    }
1206	
1207	    function toggleTheme() {
1208	      const current = document.documentElement.getAttribute('data-theme') || 'system';
1209	      const next = current === 'dark' ? 'light' : current === 'light' ? 'system' : 'dark';
1210	      if (next === 'system') {
1211	        document.documentElement.removeAttribute('data-theme');
1212	      } else {
1213	        document.documentElement.setAttribute('data-theme', next);
1214	      }
1215	    }
1216	
