   ======================================================================== */

.header {
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
  padding-bottom: var(--gap-lg);
  border-bottom: 1px solid var(--border-light);
}

.header-top {
  display: flex;
  justify-content: space-between;
